HTML="""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My-AI</title><style>body{font-family:system-ui;margin:0;background:#f5f5f5;color:#222}main{max-width:900px;margin:auto;padding:24px}textarea,input{width:100%;box-sizing:border-box;padding:12px;margin:8px 0;border:1px solid #bbb;border-radius:8px}button{padding:10px 16px;border:0;border-radius:8px;cursor:pointer}pre{white-space:pre-wrap;background:#fff;padding:16px;border-radius:8px;min-height:100px}.card{background:#fff;padding:18px;border-radius:12px;margin:12px 0}</style></head><body><main><h1>My-AI</h1><p>Local personal learning and coding agent</p><div class="card"><h2>Chat</h2><textarea id="msg" rows="5"></textarea><button onclick="chat()">Send</button><pre id="out"></pre></div><div class="card"><h2>Autonomous learning</h2><button onclick="learn('Python')">Python step</button><button onclick="learn('C')">C step</button><pre id="learnout"></pre></div><div class="card"><h2>Project planner</h2><textarea id="goal" rows="3" placeholder="Describe a project"></textarea><button onclick="plan()">Plan</button><pre id="planout"></pre></div><script>async function post(p,b){let r=await fetch(p,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});let j=await r.json();if(!r.ok)throw Error(j.detail||'Request failed');return j}async function chat(){try{out.textContent='...';out.textContent=(await post('/chat',{message:msg.value})).answer}catch(e){out.textContent=e}}async function learn(language){try{learnout.textContent='...';learnout.textContent=JSON.stringify(await post('/learning/step',{language}),null,2)}catch(e){learnout.textContent=e}}async function plan(){try{planout.textContent=JSON.stringify(await post('/projects/plan',{goal:goal.value}),null,2)}catch(e){planout.textContent=e}}</script></main></body></html>"""
def page(): return HTML
